import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        TodoService s = new TodoService(new TodoRepositoryMemori());
        s.tambah("Belajar Java");
        s.tambah("Beli kopi");
        s.tambah("Latihan JAVA OOP");
        s.selesaikan(1);
        s.selesaikan(2);
        System.out.println(s.cari("java"));
        System.out.println(s.jumlahSelesai() + " dari " + s.semua().size());
    }
}

class Todo {
    private final int id;
    private final String judul;
    private boolean selesai;

    Todo(int id, String judul) {
        this.id = id;
        this.judul = judul;
    }

    int getId() {
        return id;
    }

    String getJudul() {
        return judul;
    }

    boolean isSelesai() {
        return selesai;
    }

    void selesaikan() {
        selesai = true;
    }

    @Override
    public String toString() {
        return id + ". [" + (selesai ? "x" : " ") + "] " + judul;
    }
}

interface TodoRepository {
    Todo simpan(String judul);

    List<Todo> semua();

    Todo cari(int id);

    boolean hapus(int id);

    void perbarui(Todo todo);
}

class TodoRepositoryMemori implements TodoRepository {
    private final List<Todo> data = new ArrayList<>();
    private int idBerikut = 1;

    public Todo simpan(String judul) {
        Todo t = new Todo(idBerikut++, judul);
        data.add(t);
        return t;
    }

    public List<Todo> semua() {
        return new ArrayList<>(data);
    }

    public Todo cari(int id) {
        for (Todo t : data) {
            if (t.getId() == id) {
                return t;
            }
        }
        return null;
    }

    public boolean hapus(int id) {
        Todo t = cari(id);
        return t != null && data.remove(t);
    }

    public void perbarui(Todo todo) {
        // data di memori sudah ikut berubah, tidak ada yang perlu disimpan
    }
}

class TodoTidakDitemukanException extends RuntimeException {
    TodoTidakDitemukanException(int id) {
        super("Todo nomor " + id + " tidak ditemukan");
    }
}

class TodoService {
    private final TodoRepository repo;

    TodoService(TodoRepository repo) {
        this.repo = repo;
    }

    Todo tambah(String judul) {
        if (judul == null || judul.trim().isEmpty()) {
            throw new IllegalArgumentException("Judul tidak boleh kosong");
        }
        if (judul.trim().length() > 50) {
            throw new IllegalArgumentException("Judul maksimal 50 huruf");
        }
        return repo.simpan(judul.trim());
    }

    void selesaikan(int id) {
        Todo t = repo.cari(id);
        if (t == null) {
            throw new TodoTidakDitemukanException(id);
        }
        t.selesaikan();
        repo.perbarui(t);
    }

    void hapus(int id) {
        if (!repo.hapus(id)) {
            throw new TodoTidakDitemukanException(id);
        }
    }

    List<Todo> semua() {
        return repo.semua();
    }

    List<Todo> cari(String kata) {
        String k = kata.toLowerCase();
        return repo.semua().stream()
                .filter(t -> t.getJudul().toLowerCase().contains(k))
                .collect(Collectors.toList());
    }

    long jumlahSelesai() {
        return repo.semua().stream().filter(Todo::isSelesai).count();
    }
}

